apiVersion: v1
kind: Secret
metadata:
  name: ngc-docker-registry-secret
  labels:
    app.kubernetes.io/name: sdg-workflow-controller
    app.kubernetes.io/component: docker-registry-secret
    app.kubernetes.io/managed-by: helm
type: kubernetes.io/dockerconfigjson
data:
  .dockerconfigjson: {{ template "imagePullSecret" . }}
{{- end }}

{{/*
Generate docker config for NGC registry
*/}}
{{- define "imagePullSecret" }}
{{- with .Values.global.secrets.ngcDockerRegistrySecret }}
{{- $username := .username | default "$oauthtoken" }}
{{- $server := .server | default "nvcr.io" }}
{{- $email := .email | default "" }}
{{- printf "{\"auths\":{\"%s\":{\"username\":\"%s\",\"password\":\"%s\",\"email\":\"%s\",\"auth\":\"%s\"}}}" $server $username .password $email (printf "%s:%s" $username .password | b64enc) | b64enc }}
