metadata:
  name: multistorageclient-configuration-secret
  labels:
    app.kubernetes.io/component: multistorageclient-configuration-secret
    {{- include "sdg-workflow-controller.labels" . | nindent 4 }}
type: Opaque
stringData:
  multistorageclient_configuration_secret: |-
    {
      "profiles": {
        "{{ $inputBucket }}": {
          "storage_provider": {
            "type": "s3",
            "options": {
              "base_path": "{{ $inputBucket }}",
              "region_name": "{{ $inputRegion }}",
              "endpoint_url": "{{ $inputEndpoint }}"
            }
          },
          "credentials_provider": {
            "type": "S3Credentials",
            "options": {
              "access_key": "{{ $inputAccessKey }}",
              "secret_key": "{{ $inputSecretKey }}"
            }
          }
        }
        {{- if or (ne $inputBucket $outputBucket) (ne $inputRegion $outputRegion) }},
        "{{ $outputBucket }}": {
          "storage_provider": {
            "type": "s3",
            "options": {
              "base_path": "{{ $outputBucket }}",
              "region_name": "{{ $outputRegion }}",
              "endpoint_url": "{{ $outputEndpoint }}"
            }
          },
          "credentials_provider": {
            "type": "S3Credentials",
            "options": {
              "access_key": "{{ $outputAccessKey }}",
              "secret_key": "{{ $outputSecretKey }}"
            }
          }
        }
        {{- end }}
      },
      "path_mapping": {
        "https://{{ $inputBucket }}.s3.{{ $inputRegion }}.amazonaws.com/": "msc://{{ $inputBucket }}/",
        "s3://{{ $inputBucket }}/": "msc://{{ $inputBucket }}/"
        {{- if or (ne $inputBucket $outputBucket) (ne $inputRegion $outputRegion) }},
        "https://{{ $outputBucket }}.s3.{{ $outputRegion }}.amazonaws.com/": "msc://{{ $outputBucket }}/",
        "s3://{{ $outputBucket }}/": "msc://{{ $outputBucket }}/"
        {{- end }}
      }
    }
{{- end }}

