metadata:
  name: airflow-api-connection-secret
  labels:
    app.kubernetes.io/component: airflow-api-connection-secret
    {{- include "sdg-workflow-controller.labels" . | nindent 4 }}
type: Opaque
{{- $defaultUser := ((((.Values).airflow).createUserJob).defaultUser) | default dict }}
stringData:
  connection: {{ printf "{\"conn_type\": \"http\", \"host\": \"%s-api-server\", \"schema\": \"http\", \"port\": 8080, \"login\": %s, \"password\": %s}" (include "sdg-workflow-controller.fullname" .) (toJson ($defaultUser.username | default "")) (toJson ($defaultUser.password | default "")) | quote }}

